import { mapState } from "vuex";
import { getDivisionOrder } from "@/api/order";
import { getDivisionOptionApi, getDivisionAgentOptionApi, getDivisionOrderExportApi } from "@/api/agent"
import timeOptions from "@/utils/timeOptions";
import exportExcel from "@/utils/newToExcel.js";
export default {
  data() {
    return {
      openErp: false,
      tbody: [],
      num: [],
      orderDatalist: null,
      loading: false,
      FromData: null,
      total: 0,
      orderId: 0,
      pagination: {
        page: 1,
        limit: 15,
        real_name: "",
        field_key: "",
        time: "",
        division_id:"",
        division_agent_id:""
      },
      options: timeOptions,
      timeVal: [],
      orderList: [],
      divisionList:[],
      divisionAgentList:[]
    };
  },
  computed: {
    ...mapState("order", ["orderChartType"]),
    // ...mapState("admin/layout", ["isMobile"]),
    labelWidth() {
      return this.isMobile ? undefined : 96;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
    showDivisionFilter(){
      return this.$store.state.admin.user.info.division_id;
    }
  },
  created() {
    this.getDivisionOption();
    this.getOrderList();
    //
  },
  methods: {
    getDivisionOption(){
      getDivisionOptionApi().then(res=>{
        this.divisionList = res.data;
      })
    },
    getDivisionAgentOption(){
      getDivisionAgentOptionApi(this.pagination.division_id).then(res=>{
        this.divisionAgentList = res.data;
        console.log(res.data);
      })
    },
    agentSearch(){
      this.getDivisionAgentOption();
      this.pagination.page = 1;
      this.getOrderList();
    },
    search() {
      this.pagination.page = 1;
      this.getOrderList();
    },
    // 具体日期搜索()；
    onchangeTime(e) {
      this.pagination.page = 1;
      this.timeVal = e;
      this.pagination.time = this.timeVal[0] ? this.timeVal.join("-") : "";
    },

    // 订单列表
    getOrderList() {
      this.loading = true;
      getDivisionOrder(this.pagination)
        .then((res) => {
          const { count, data, num } = res.data;
          this.orderList = data;
          this.total = count;
          this.loading = false;
        })
        .catch((err) => {
          this.loading = false;
          this.$Message.error(err.msg);
        });
    },
    clearTap(e) {
      this.pagination.page = 1;
      this.getOrderList();
    },
    // 分页
    pageChange(index) {
      this.pagination.page = index;
      this.getOrderList();
    },
    nameSearch() {
      this.pagination.page = 1;
      this.getOrderList();
    },
    async exports() {
      let [th, filekey, data, fileName] = [[], [], [], ""];
      //   let fileName = "";
      let excelData = JSON.parse(JSON.stringify(this.pagination));
      excelData.page = 1;
      excelData.limit = 100;
      for (let i = 0; i < excelData.page + 1; i++) {
        let lebData = await this.getExcelData(excelData);
        if (!fileName) fileName = lebData.filename;
        if (!filekey.length) {
          filekey = lebData.filekey;
        }
        if (!th.length) th = lebData.header;
        if (lebData.export.length) {
          data = data.concat(lebData.export);
          excelData.page++;
        } else {
          exportExcel(th, filekey, fileName, data);
          return;
        }
      }
    },
    getExcelData(excelData) {
      return new Promise((resolve, reject) => {
        getDivisionOrderExportApi(excelData).then((res) => {
          return resolve(res.data);
        });
      });
    },
    //getDivisionOrderExportApi
  },
};
